import {relatedMedia} from './study-media.mjs';
// Selected, unmodified AWS Architecture Icons; see ASSET-SOURCES.md.
import {icons} from './icon-catalog.mjs';
export {icons};
export const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const esc=escapeHTML;
const glyphs={
 'sam':'M17 14l-7 10 7 10m14-20 7 10-7 10m-10-4 6-12',
 'service-quotas':'M9 30a15 15 0 1 1 30 0m-15-2 8-10M10 33h28',
 'migration-hub':'M11 12l13 12 13-12m-26 24 13-12 13 12m-18-12a5 5 0 1 0 10 0 5 5 0 1 0-10 0',
 'appstream-2-0-workspaces-applications':'M8 13h32v22H8zM18 39h12M21 19l9 5-9 5z',
 'cost-allocation-tags':'M9 12h14l16 16-12 12L9 22zM15 17h2v2h-2z',
 'schema-conversion-tool-sct':'M6 13h13v21H6zM29 13h13v21H29zM18 24h11m-5-5 5 5-5 5',
 'reserved-instances':'M10 13h28v24H10zM10 20h28m-22-9v5m16-5v5m-15 12 5 4 9-8'
};
export function iconHTML(id,size=48){const i=icons[id];return i?.src?`<img class="aws-icon" src="${i.src}" width="${size}" height="${size}" alt="" loading="lazy" decoding="async">`:`<svg class="aws-icon concept-icon" width="${size}" height="${size}" viewBox="0 0 48 48" aria-hidden="true"><rect x="2" y="2" width="44" height="44" rx="12" fill="#edf2eb"/><path d="${glyphs[id]||'M12 15h24v18H12z'}" fill="none" stroke="#34634f" stroke-width="2"/></svg>`;}
export const iconNote=id=>icons[id]?.kind==='concept'?'Concept illustration':icons[id]?.kind==='family'?'AWS service-family icon':'AWS architecture icon';
export function lessonVisuals(lesson,data){const services=data.categories.flatMap(c=>c.services).filter(s=>s.lesson===lesson.id);if(!services.length)return '';return `<section class="lesson-visuals" aria-label="Visual service anchors"><div class="visual-heading"><span class="section-context">SEE THE SERVICES</span><a href="#visuals">Explore visual atlas ↗</a></div><div class="lesson-icon-strip">${services.map(s=>`<a class="lesson-icon" href="#visuals/${s.id}">${iconHTML(s.id)}<span>${esc(s.name)}</span></a>`).join('')}</div><p class="fine">Hubungkan icon → fungsi → pembeda. Click a service to explore its memory card.</p>${relatedMedia(services.map(s=>s.id))}</section>`;}
const card=(s,selected=false)=>`<button class="atlas-card ${selected?'chosen':''}" data-service="${s.id}" aria-pressed="${selected}"><span class="atlas-card-top">${iconHTML(s.id,52)}<span class="atlas-open" aria-hidden="true">↗</span></span><strong>${esc(s.name)}</strong><span>${esc(s.cue)}</span><small>${esc(s.group)}</small></button>`;
const detail=(s,showMedia=true)=>`<div class="detail-identity">${iconHTML(s.id,64)}<div><span class="section-context">${esc(s.group)}</span><h2>${esc(s.name)}</h2><p>${esc(s.expansion||s.name)}</p></div></div><p class="icon-credit">${iconNote(s.id)}${icons[s.id]?.kind==='family'?' · '+esc(icons[s.id].label):''}</p><div class="visual-memory"><span>MEMORY ANCHOR · INGAT</span><p>${esc(s.cue)}</p></div><h3>The job · Fungsinya</h3><p>${esc(s.use)}</p><h3>The deciding detail</h3><p>${esc(s.compare)}</p>${s.update?`<div class="atlas-lifecycle"><strong>${esc(s.update.tag)}</strong><p>${esc(s.update.note)}</p><a href="${esc(s.update.url)}" target="_blank" rel="noopener">AWS notice ↗</a></div>`:''}${showMedia&&relatedMedia([s.id])?'<details class="atlas-related"><summary>See diagrams &amp; videos</summary>'+relatedMedia([s.id])+'</details>':''}<details class="visual-recall"><summary>Recall: explain it without the name</summary><p>Dengan kata-katamu sendiri: masalah apa yang diselesaikan layanan ini? Apa pembeda dari alternatif terdekat? Then check your explanation against the two sections above.</p></details><a class="button primary" href="#learn/${s.lesson}">Understand the full lesson →</a>`;
export function renderAtlas(root,data,initial){
 const all=data.categories.flatMap(c=>c.services.map(s=>({...s,category:c.id})));let selected=all.find(s=>s.id===initial)||all.find(s=>s.id==='ec2')||all[0],category=selected.category,query='',compare=[];
 root.innerHTML=`<div class="atlas-heading"><div><p class="section-context">VISUAL LIBRARY / 176 SERVICES & FEATURES</p><h1>Service atlas.</h1><p class="lede">Kenali ikonnya. Pahami fungsinya. Bandingkan sebelum memilih.</p></div><a class="button" href="#architecture">See architecture stories ↗</a></div><div class="atlas-toolbar"><label>Search by name or purpose<input type="search" id="atlas-search" placeholder="S3, antrian, enkripsi, temporary…"></label><label>Explore a category<select id="atlas-category"><option value="all">All categories</option>${data.categories.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></label><span id="atlas-count" role="status"></span></div><div class="atlas-layout"><div><div id="atlas-grid" class="atlas-grid"></div><p class="fine">Icons help recognition; the use case and constraints determine the design. <a href="https://aws.amazon.com/architecture/icons/" target="_blank" rel="noopener">Icon source: AWS ↗</a></p></div><aside class="atlas-detail" id="atlas-detail" tabindex="-1" aria-label="Selected service"></aside></div><section class="atlas-comparison" id="atlas-comparison" aria-label="Service comparison"></section>`;
 const by=id=>root.querySelector('#'+id);
 function drawCards(){const list=all.filter(s=>(category==='all'||s.category===category)&&[s.name,s.expansion,s.cue,s.use,s.compare].join(' ').toLowerCase().includes(query.toLowerCase()));by('atlas-grid').innerHTML=list.length?list.map(s=>card(s,s.id===selected.id)).join(''):'<div class="empty"><h2>No matching service.</h2><p>Try a shorter name or choose All categories.</p></div>';by('atlas-count').textContent=list.length+' services & features';}
 function drawDetail(){by('atlas-detail').innerHTML=detail(selected)+`<button id="atlas-add" class="button">${compare.includes(selected.id)?'Remove from comparison':'Compare this service'}</button><p id="compare-status" role="status">${compare.length}/2 selected for side-by-side comparison.</p>`;by('atlas-add').onclick=()=>{if(compare.includes(selected.id))compare=compare.filter(id=>id!==selected.id);else if(compare.length<2)compare.push(selected.id);else{by('compare-status').textContent='Two services selected. Remove one below to compare another.';return;}drawDetail();drawCompare();};}
 function drawCompare(){by('atlas-comparison').innerHTML=compare.length?`<div class="visual-heading"><h2>Spot the difference.</h2><span>${compare.length}/2 services selected</span></div>${compare.length===1?'<p>Select another service above, then choose “Compare this service”. You can switch categories.</p>':''}<div class="comparison-pair">${compare.map(id=>{const s=all.find(x=>x.id===id);return `<article>${detail(s,false)}<button data-remove="${id}" aria-label="Remove ${esc(s.name)} from comparison">Remove from comparison</button></article>`;}).join('')}</div>`:'';}
 by('atlas-category').value=category;by('atlas-category').onchange=e=>{category=e.target.value;drawCards();};by('atlas-search').oninput=e=>{query=e.target.value;if(query){category='all';by('atlas-category').value='all';}drawCards();};
 root.addEventListener('click',e=>{const b=e.target.closest('[data-service]'),r=e.target.closest('[data-remove]');if(b){selected=all.find(s=>s.id===b.dataset.service);history.replaceState(null,'','#visuals/'+selected.id);drawCards();drawDetail();by('atlas-detail').focus({preventScroll:true});if(globalThis.matchMedia?.('(max-width: 900px)').matches)by('atlas-detail').scrollIntoView({block:'start'});}if(r){compare=compare.filter(id=>id!==r.dataset.remove);drawDetail();drawCompare();}});
 drawCards();drawDetail();drawCompare();
}
